"""Render auditable results and a standalone scientific figure from retained data."""
from dental_release.paths import expand as _release_expand
from pathlib import Path
import collections, datetime, hashlib, json, math
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
LANE = Path(__file__).resolve().parents[1]

def read(p):
    return json.loads((LANE / p).read_text())

def save(p, d):
    (LANE / p).write_text(json.dumps(d, indent=2, ensure_ascii=False) + '\n')

def round4():
    file = LANE / 'raw/R4_FE_runs.jsonl'
    runs = [json.loads(l) for l in file.read_text().splitlines()] if file.exists() else []
    good = {r['id']: r for r in runs if r.get('ok')}
    vals = []
    for r in runs:
        if not r.get('ok'):
            vals.append({'id': r['id'], 'solver_success': False, 'failure': r.get('fail')})
            continue
        y = r['u_load_along_F_um']
        ratio = y / 550
        vals.append({'id': r['id'], 'solver_success': True, 'projected_system_motion_um': y, 'observed_system_mean_um': 550, 'observed_system_sd_um': 43.9, 'observed_n': 3, 'FE_over_measured': ratio, 'magnitude_factor2_gate': 0.5 <= ratio <= 2, 'slip_max_um': r['slip_max_um'], 'slip_validation': 'UNKNOWN: no directly paired interface measurement', 'prestress_MPa': r['prestress_p_rad'], 'fixed_penalty_MPa_per_mm': r['K_pen'], 'source_material_MPa': {'cortex': r['spec']['E_c'], 'foam': r['spec']['E_s']}, 'mu': r['spec']['mu'], 'nodes': r['info']['n_nodes'], 'runtime_s': r['t_total'], 'motion_resolution': 'PER_POINT for FE, POPULATION for measured mean', 'slip_resolution': 'PER_SURFACE_REGION (sampled FE interface maximum)'})
    complete = len(runs) == 5
    reproduction = None
    factorial = None
    if 'R4_default' in good:
        b = good['R4_default']['u_load_along_F_um']
        reproduction = {'historical_um': 123.56659932035807, 'new_um': b, 'relative_change': b / 123.56659932035807 - 1, 'gate_10percent': abs(b / 123.56659932035807 - 1) <= 0.1}
    if all(('R4_' + x in good for x in ['default', 'foam_only', 'cortex_only', 'both'])):
        y = {x: good['R4_' + x]['u_load_along_F_um'] for x in ['default', 'foam_only', 'cortex_only', 'both']}
        factorial = {'foam_only_gain': y['foam_only'] / y['default'], 'cortex_only_gain': y['cortex_only'] / y['default'], 'both_gain': y['both'] / y['default'], 'log_interaction': math.log(y['both'] * y['default'] / (y['foam_only'] * y['cortex_only'])), 'single_replacements_reach_275um': {x: y[x] >= 275 for x in ['foam_only', 'cortex_only']}, 'interpretation': 'controlled FE intervention at fixed initial expansion and contact penalty; pressure changes with modulus. Not real empirical causal attribution.'}
        if 'R4_both_mu06' in good:
            factorial['mu03_to06_gain'] = good['R4_both_mu06']['u_load_along_F_um'] / y['both']
    out = {'round': 'R4', 'claim_type': 'information_link', 'status': 'COMPLETE' if complete else 'RUNNING', 'verdict': 'DISCRETE_PARAMETER_INTERVENTIONS_EXECUTED' if complete else 'PENDING_FE_RUNS', 'external_referent': {'kind': 'independent_measurement', 'locator': 'doi:10.5051/jpis.2017.47.4.251; PMC5577443#T2 axial implant / oblique column', 'compared_quantity': '200 N projected abutment/crosshead displacement, source mean 550 um', 'refutes_us': True}, 'runs': vals, 'baseline_reproduction': reproduction, 'factorial_intervention': factorial, 'cause_status': 'UNKNOWN_EMPIRICAL; source E values linked, source mu .6 assumed, p0 not measured, cylindrical geometry and crush/fixture mismatch remain', 'rigorous_nonlinear_FE_enclosure': 'MISSING: only executed discrete settings, no linearized uncertainty claim', 'source_material_pretest': '66 MPa obtained by specimen-system preliminary test plus FE, 6000 MPa chosen for temperature; source values are not patient bone calibration', 'negative_control': {'injected_target_x1000_fails': all((not 0.5 <= r['u_load_along_F_um'] / 550000 <= 2 for r in good.values())), 'wrong_interface_observable_rejected': read('rounds/R1/results.json')['negative_controls']['wrong_observable_interface_gate_rejects_all']}, 'full_cost': {'successful_FE_runs': len(good), 'attempted_FE_runs': len(runs), 'solver_runtime_s': sum((r.get('t_total', 0) for r in runs)), 'threads': 4, 'reserved_ram_gb': 4, 'heavy_wrapper': True, 'no_motion_fit': True}, 'time_scale': 'SIMULTANEOUS', 'resolution': 'PER_POINT FE system, POPULATION source system; local slip PER_SURFACE_REGION'}
    (LANE / 'rounds/R4').mkdir(parents=True, exist_ok=True)
    save('rounds/R4/results.json', out)
    return out

def round5(r4):
    file = LANE / 'raw/R5_FE_runs.jsonl'
    runs = [json.loads(x) for x in file.read_text().splitlines()] if file.exists() else []
    base = next((x['projected_system_motion_um'] for x in r4['runs'] if x['id'] == 'R4_both_mu06' and x['solver_success']), None)
    vals = []
    for r in runs:
        if not r.get('ok'):
            vals.append({'id': r['id'], 'solver_success': False, 'failure': r.get('fail')})
            continue
        y = r['u_load_along_F_um']
        gain = y / base if base is not None else None
        vals.append({'id': r['id'], 'solver_success': True, 'projected_system_motion_um': y, 'FE_over_measured': y / 550, 'factor2_gate': 0.5 <= y / 550 <= 2, 'slip_max_um': r['slip_max_um'], 'motion_resolution': 'PER_POINT / POPULATION external comparison', 'slip_resolution': 'PER_SURFACE_REGION', 'prestress_MPa': r['prestress_p_rad'], 'system_gain_vs_original_expansion': gain, 'effect_25percent_gate': abs(gain - 1) >= 0.25 if gain is not None else None, 'expansion_T_c_s': [r['spec']['T_c'], r['spec']['T_s']], 'runtime_s': r['t_total']})
    out = {'round': 'R5', 'claim_type': 'information_link', 'status': 'COMPLETE' if len(runs) == 2 else 'RUNNING', 'verdict': 'PRESTRAIN_STATE_INTERVENTIONS_EXECUTED' if len(runs) == 2 else 'PENDING_FE_RUNS', 'external_referent': {'kind': 'independent_measurement', 'locator': 'doi:10.5051/jpis.2017.47.4.251 Table2, axial implant oblique loading', 'compared_quantity': 'source abutment/crosshead displacement mean550um', 'refutes_us': True}, 'baseline_R4_both_mu06_um': base, 'runs': vals, 'empirical_cause': 'UNKNOWN: no independent pressure/crush/fixture observation, discrete simulated branch only', 'modeled_input_gate': {'relative_effect_threshold': 0.25, 'any_successful_case_reaches_gate': any((v.get('effect_25percent_gate', False) for v in vals)), 'interpretation': 'Discrete modeled dependence only; never identifies empirical preload cause'}, 'negative_controls': {'injected_target_x1000_fails': all((not 0.5 <= r['u_load_along_F_um'] / 550000 <= 2 for r in runs if r.get('ok'))), 'wrong_interface_observable_rejected': read('rounds/R1/results.json')['negative_controls']['wrong_observable_interface_gate_rejects_all']}, 'direct_local_slip_gate': 'UNKNOWN: system comparison cannot validate slip', 'nonlinear_parameter_enclosure': 'MISSING; no affine sensitivity or uncertainty extrapolation', 'full_cost': {'FE_runs': len(runs), 'solver_runtime_s': sum((r.get('t_total', 0) for r in runs)), 'reserved_ram_gb': 4, 'threads': 4, 'heavy_wrapper': True}, 'resolution': 'PER_POINT system / POPULATION external mean / PER_SURFACE_REGION slip', 'time_scale': 'SIMULTANEOUS'}
    (LANE / 'rounds/R5').mkdir(parents=True, exist_ok=True)
    save('rounds/R5/results.json', out)
    return out

def figure(r1, r2, r3, r4):
    (fig, axs) = plt.subplots(2, 2, figsize=(11, 8), layout='constrained')
    a = axs[0, 0]
    x = np.arange(2)
    a.bar(x - 0.15, [43, 43], width=0.3, label='Axial mean (reported)', color='#4276a6')
    a.bar(x + 0.15, [57, 112], width=0.3, label='Total mean (reported)', color='#ba694c')
    a.set_xticks(x, ['B11 threaded', 'MT root analogue'])
    a.set_ylabel('Motion (µm), population mean')
    a.set_title('Independent measurement: same axial summary')
    a.legend(fontsize=8, loc='upper left')
    a.text(0.03, 0.8, 'PMC10792929 Table 1; 50 N\nSame rounded axial mean; different total mean', transform=a.transAxes, va='top', fontsize=8)
    a = axs[0, 1]
    old = r1['historical_measured_material_link']
    for (i, d) in enumerate(old):
        a.bar(i - 0.23, d['baseline_predicted_system_um'], 0.23, color='#4276a6', label='K27 original' if i == 0 else None)
        a.bar(i, d['modified_predicted_system_um'], 0.23, color='#c49b4b', label='BOTH material moduli linked' if i == 0 else None)
        a.bar(i + 0.23, d['measured_system_um'], 0.23, color='#555555', label='Independent system measurement' if i == 0 else None)
    a.set_xticks([0, 1], ['Axial 200 N', '45° / 200 N'])
    a.set_ylabel('System motion (µm)')
    a.set_title('Historical material link leaves a residual')
    a.legend(fontsize=8, loc='upper left')
    a.text(0.03, 0.76, 'PMC5577443 Table 2\nSystem displacement, not local slip', transform=a.transAxes, va='top', fontsize=8)
    a = axs[1, 0]
    for (i, (name, d)) in enumerate(r3['cases'].items()):
        (lo, hi) = d['rigorous_sampled_peak_interval_um']
        a.errorbar(i, (lo + hi) / 2, yerr=(hi - lo) / 2, fmt='o', capsize=8, color='#4276a6')
    a.axhline(50, color='#555555', linestyle='--', label='50 / 150 µm research band')
    a.axhline(150, color='#555555', linestyle='--')
    a.set_xticks([0, 1], ['Spread support', 'Central support'])
    a.set_ylabel('Sampled regional peak (µm)')
    a.set_title('Own fixture: exact summaries, unequal motion')
    a.legend(fontsize=8, loc='upper left')
    a.text(0.03, 0.84, 'Simulation only; prescribed ±1 µm reading boxes\nNo empirical interface or healing validation', transform=a.transAxes, va='top', fontsize=8)
    a = axs[1, 1]
    rr = [v for v in r4['runs'] if v['solver_success']]
    if rr:
        a.bar(range(len(rr)), [d['projected_system_motion_um'] for d in rr], color='#4276a6')
        a.axhline(550, color='#555555', label='Measured system mean 550 µm')
        a.axhspan(550 - 43.9, 550 + 43.9, color='#888888', alpha=0.15)
        a.set_xticks(range(len(rr)), [d['id'].replace('R4_', '').replace('_', '\n') for d in rr], fontsize=8)
        a.legend(fontsize=8)
    else:
        a.text(0.5, 0.5, 'Matched FE interventions pending', ha='center', transform=a.transAxes)
    a.set_ylabel('System motion (µm)')
    a.set_title('New FE: separated material changes')
    fig.suptitle('X56 — identify what the motion measurement actually resolves', fontsize=14)
    fig.savefig(LANE / 'FIGURE_X56.png', dpi=160)
    fig.savefig(LANE / 'FIGURE_X56.pdf')
    plt.close(fig)

def main():
    (r1, r2, r3) = [read('rounds/' + r + '/results.json') for r in ['R1', 'R2', 'R3']]
    r4 = round4()
    r5 = round5(r4)
    ledger = read('raw/screening_ledger.json')
    counter = collections.Counter((d['screening_decision'] for d in ledger))
    rejected = sum((v for (k, v) in counter.items() if k.startswith('REJECT')))
    groups = {}
    for row in read('raw/measurements.json'):
        key = (row['study'], row['implant'], row['substrate'], row.get('rho_g_cm3'), row.get('cortex_mm'), row.get('fixation'))
        if key not in groups:
            groups[key] = {'study': row['study'], 'implant': row['implant'], 'substrate': row['substrate'], 'foam_density_g_cm3': row.get('rho_g_cm3'), 'cortical_surrogate_mm': row.get('cortex_mm'), 'reported_bone_class': row.get('biological_class'), 'human_bone_class': False, 'source_table': row['table_locator'], 'source_measurements': [], 'interface_50_150um_decision': 'UNKNOWN_NO_DIRECT_LOCAL_BONE_IMPLANT_REFERENCE', 'resolution': 'POPULATION source means; no individual interface decision'}
        groups[key]['source_measurements'].append({'row_id': row['id'], 'force_N': row['force_N'], 'observed_proxy_mean_um': row['motion_um'], 'sd_um': row['sd_um'], 'operator': row['observation_operator']})
    per_group = list(groups.values())
    save('raw/interface_threshold_decisions.json', per_group)
    regfiles = sorted(LANE.glob('PREREG*.json'))
    results = {'lane': 'X56-micromotion', 'claim_type': 'information_link', 'producer_review_state': 'PENDING_INDEPENDENT_REVIEW', 'primary_outcome': 'Published table links constrain K27 system motion and refute axial-summary sufficiency; empirical local-interface magnitude and healing thresholds remain UNKNOWN', 'external_referent': {'kind': 'independent_measurement', 'locator': 'doi:10.5051/jpis.2017.47.4.251 Table 2; doi:10.4103/ccd.ccd_788_18 Table 1; doi:10.3390/ma14247886 Table 1; doi:10.1186/s12903-024-03854-1 Table 1', 'compared_quantity': 'loaded study-defined displacement means; local interface slip not measured in included tables', 'refutes_us': True}, 'measurement_counts': r1['counts'], 'screening': {'paths_screened': len(ledger), 'unique_publications': len({d['pmcid'] for d in ledger}), 'retained_paths': len(ledger) - rejected, 'retained_independent_motion_studies': 4, 'rejected_paths': rejected, 'rejected_fraction': rejected / len(ledger), 'reasons': dict(counter), 'duplicate_retained_path': 'PMC10792929 in corpus and old cache; counts as ONE study', 'method': 'Targeted primary source rereading plus automated title/article-type/table-unit screening; not an exhaustive systematic review. No claim that no direct local interface study exists anywhere in corpus or literature.'}, 'rounds': {'R1': r1, 'R2': r2, 'R3': r3, 'R3A': read('rounds/R3A/results.json'), 'R4': r4, 'R5': r5}, 'per_implant_type_bone_class_interface_threshold': 'UNKNOWN for all included combinations; no local paired bone-implant field or patient calibrated load/material state', 'per_implant_substrate_groups': per_group, 'source_claims': 'Only group-level lab proxies retained; no individual or human bone-class safety inference', 'phenomenological_debts': [{'quantity': 'fixture support stiffness', 'replace_with': 'independent measured local bone-referenced response to calibrated wrenches'}, {'quantity': 'source-linked effective foam/cortex elastic closures, 66/6000 MPa', 'replace_with': 'same-batch independently measured local strain/force and unload curve, separated from fixture and crushing'}, {'quantity': 'assumed mu .3/.6 and insertion-prestrain to pressure closure', 'replace_with': 'matched surface/substrate normal-tangential calibration and independently measured initial contact state'}, {'quantity': 'computational contact penalty and stick slope', 'replace_with': 'verified contact-law/discretization convergence and independently constrained interface response; never equate penalty with physical interface stiffness'}, {'quantity': '±1 um reading error box', 'replace_with': 'actual instrument calibration and marker localization error bound; sensor resolution alone insufficient'}, {'quantity': '50–150 um biological band', 'replace_with': 'matched implant-specific gap tissue, load-cycle history and independently measured healing endpoint'}], 'edges': [{'from': 'PMC5577443#T2', 'to': 'DENT-IF-BI-MICROMOTION', 'quantity': 'projected system displacement', 'resolution': 'POPULATION (finest common for published grouped means and matched condition prediction)', 'observation_location': 'PER_POINT at abutment load location; not interface', 'time_scale': 'SIMULTANEOUS', 'state': 'PENDING_INDEPENDENT_REVIEW'}, {'from': 'PMC5577443#T1 plus source pretest/temperature closure', 'to': 'K27 separate foam/cortex material-law inputs', 'quantity': 'effective elastic modulus closures, MPa', 'resolution': 'PHENOMENOLOGICAL; applied separately to foam/cortex PER_SURFACE_REGION in FE', 'time_scale': 'SIMULTANEOUS', 'state': 'PENDING_INDEPENDENT_REVIEW; no promotion to independently measured local modulus'}, {'from': 'PROC_insert K26 initial pressure closure', 'to': 'K27 initial expansion/contact state', 'quantity': 'insertion leaves initial per-layer pressure state for later loading', 'resolution': 'PER_SURFACE_REGION at bone-layer contact region; no local measured pressure field', 'time_scale': 'HANDOVER', 'state': 'UNKNOWN_EMPIRICAL_CALIBRATION'}, {'from': 'PMC10792929#Tab1', 'to': 'local translation/rotation measurement port', 'quantity': 'axial and total displacement; grouped rounded means', 'resolution': 'POPULATION; PER_POINT observation coordinates retained, no patient-level promotion', 'time_scale': 'SIMULTANEOUS', 'state': 'PENDING_INDEPENDENT_REVIEW'}, {'from': 'local relative motion history', 'to': 'osseointegration state', 'quantity': 'mechanical exposure -> healing initial conditions', 'resolution': 'PER_SURFACE_REGION', 'time_scale': 'HANDOVER', 'state': 'UNKNOWN_BIOLOGICAL_CLOSURE'}], 'prereg_hashes': {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in regfiles}, 'frozen_prediction_records': read('FROZEN_PREDICTIONS.json'), 'large_arrays': [], 'total_intermediate_limit_bytes': 3000000000, 'data_directory': _release_expand('@DENTAL_WORK_ROOT@/X56-micromotion'), 'sources': read('raw/source_manifest.json'), 'raw_source_checks': read('raw/source_checks.json'), 'retained_artifact_hashes': {str(p.relative_to(LANE)): hashlib.sha256(p.read_bytes()).hexdigest() for p in [LANE / 'raw/measurements.json', LANE / 'raw/historical_runs.json', LANE / 'raw/R4_FE_runs.jsonl', LANE / 'raw/R5_FE_runs.jsonl'] if p.exists()}, 'reproduction_code_hashes': {str(p.relative_to(LANE)): hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((LANE / 'code').glob('*.py')) + [LANE / 'run_all.sh', LANE / 'demo_inputs/spread_support.json']}, 'full_cost': {'new_FE_attempts': r4['full_cost']['attempted_FE_runs'] + r5['full_cost']['FE_runs'], 'new_FE_runtime_s': r4['full_cost']['solver_runtime_s'] + r5['full_cost']['solver_runtime_s'], 'historical_reused_FE_runtime_s': r1['full_cost'].get('historical_FE_runtime_s'), 'source_screening_paths': len(ledger), 'table_measurement_rows': 26, 'study_excluded_fits': 2, 'own_fixture_corner_evaluations': 512, 'empirical_lab_acquisition': 'NOT_PERFORMED; no new empirical measurement cost claimed', 'fit_cost': 'No motion fit in the seven new FE interventions; R1 has two whole-study fits', 'fallback': 'retain UNKNOWN for unobserved local interface, initial pressure, fixture/crushing and healing'}, 'next_construction': 'Measured nonlinear local interface test with 2 local implant+bone marker regions, 2 independent in-plane wrenches and third-wrench validation; characterize residual rotation/nonrigid field, crush and prestress independently'}
    save('results.json', results)
    figure(r1, r2, r3, r4)
    rows = '\n'.join(('| ' + d['id'].replace('R4_', '') + ' | ' + (f"{d['projected_system_motion_um']:.2f} | {d['FE_over_measured']:.3f} | {d['slip_max_um']:.2f}" if d['solver_success'] else 'FAIL | — | —') + ' |' for d in r4['runs']))
    prestrainrows = '\n'.join(('| ' + d['id'] + ' | ' + (f"{d['projected_system_motion_um']:.2f} | {d['FE_over_measured']:.3f} | {d['system_gain_vs_original_expansion']:.3f}" if d['solver_success'] and d['system_gain_vs_original_expansion'] is not None else 'FAIL/PENDING | — | —') + ' |' for d in r5['runs']))
    r4description = 'New FE is still ongoing.'
    if r4['factorial_intervention'] is not None:
        ff = r4['factorial_intervention']
        r4description = f"The foam change gives {ff['foam_only_gain']:.3f}× system movement, short-term change {ff['cortex_only_gain']:.3f}× and combination {ff['both_gain']:.3f}×. Both are needed for factor -2 - gate in the tested 45° case. These discrete simulated quotas have no rigorous parameter inclusion. μ=0,3 → 0,6 provides {ff.get('mu03_to06_gain', float('nan')):.3f}× in exactly this state ; no frictional contribution in real bone is thus identified."
    body = f"""# K27 : source-linked micromotion and what remains\n\nFour local primary studies provide 26 with tabular movement measurements. They determine how the measured **system/marker motion** varies with load, material and observation. No included table measures local parade bone – implant - sliding ; threshold 50 – 150 µm cannot therefore be determined by implant type and human bone class.\n\nDe {len(per_group)} source-specific implant/substrate groups' loads, means, SD and operators are in `raw/interface_threshold_decisions.json`; each group is explicitly allowed UNKNOWN for the border crossing threshold. Foam density and bovine class do not replace the human bone class.\n\nReference : [Sugiura 2017 , Table 2 ](https://doi.org/10.5051/jpis.2017.47.4.251), [Sugiura 2019 , Table 1 ](https://doi.org/10.4103/ccd.ccd_788_18), [ 2021 , Table 1 ](https://doi.org/10.3390/ma14247886), [Aldesoki 2024 , Table 1 ](https://doi.org/10.1186/s12903-024-03854-1). Raw cellokators, filehashars, devices, cargo and observation are available in `raw/measurements.json`. Published funds are POPULATION , with PER_POINT measurement position specified; they provide no individual guarantee.\n\n## What's changed\n\nK27 receives an explicit source bound measurement operator and a executable local-referenced translation-rotation port in its own lane. A query needs ground positions, bone references and two independent load vectors. It brings back rigorously enclosed regional motion intervals over an explicit linear, reversible branch. Missing bone reference gives UNKNOWN . A biological conclusion requires a separate healing model.\n\nThe old material change set **both** foam 202,50 → 66 MPa and shortex 16 700 → 6 000 MPa . The decreased geometric factor of the system error from approximately 5,85 to {r1['remaining_geometric_system_underprediction_factor']:.3f}; it is not a measured foam-cause premium. Contact penalties and achieved pressure were also changed. The first report/code of misinterpretation is preserved under `rounds/R1/` .\n\n### New isolated FE intervention, status {r4['status']}\n\nThe same 200 N / 45° , network 0,4 mm , initial expansion and per-layer contact penalty are maintained. Only specified material module/friction is changed. Material change with fixed expansion changes physically printing; achieved pressure is saved. Source `K_pen` / `lam` was ignored by the old implementation; only our own narrow code copy has been explicitly per-layered. No source files were changed.\n\n| Configuration | FE system µm (PER_POINT) | FE / measured ( POPULATION ) | FE glidmaximum µm (PER_SURFACE_REGION) |\n|---|---:|---:|---:|\n{rows}\n\n{r4description}\n\nThe FE effects are simulations. Except for the measurement comparison with 550 ± 43,9 µm, they are not measured mechanisms in real implant. No rigorous parameter inclusion for the non-linear FE model exists; discrete perturbations are not used as linear uncertainty propagation.\n\n### Next design: modified initial state, status {r5['status']}\n\nR5 holds the source-linked modules, μ=0,6, network and contact penalty fixed but decreasing original expansion to 0,1 × and 0 ×. At least 25 % modified system movement is the frozen gate for the initial state to be essential in the model. There is no measured cause distribution; the actual oppression is missing as reference. Singular initial branch counts as failure and is preserved.\n\n| Initial state | FE system µm | FE / measured | Ratio to original expansion |\n|---|---:|---:|---:|\n{prestrainrows}\n\nPre-registered 25 %-gate reached by any successful specimen : **{r5['modeled_input_gate']['any_successful_case_reaches_gate']}**. Final status requires both specimen ; solar failure is preserved as failure. The Local glide maximum is saved in results.json but has no direct measurement frequency and does not determine the healing threshold.\n\n## Omission of a Study\n\nTwo studies have comparable distance/crossbar operator , which is less than pre-registered three . Twelve test items provide median |ln(pred/obs)|={r1['LOSO_median_abs_log_error']:.5f}, motsvarande factor {math.exp(r1['LOSO_median_abs_log_error']):.2f}; factor -2 - gate fails . Both optical studies receive UNKNOWN in LOSO because their operator lacks a compatible other study. It is four reported folds, not four successfully pooled calibrations.\n\nThe same informed intercept control was run with the same study removal. It stands in `rounds/R1/results.json`; no algorithm advantage is claimed. Today's K27 -default is available as real comparison only for the historical matched conditions; no fictitious default predictions were created for the new implant.\n\n## Sufficientity test and next measurement\n\nTwo own mechanical state has exactly the same K0, K1 and axial compliance: identity error **0,0** to machine precision. Under the same crooked load, regional maximum 31,25 and 265,625 µm respectively (difference 234,375 µm, ratio 8,5). The smallest extension is K2 for symmetrically known K0; general asymmetric support profile needs K1 and K2. This is a separate fixture for mathematics, not external dental facits.\n\nThe independent published table provides axial agents **43 and 43 µm** for B11 and MT but total funds **57 and 112 µm** for 50 N. The difference 55 µm at POPULATION level shows why axial agents are not enough for total movement. Similarity applies to rounded-off tabulated means, not actual individual states. Form, reinfixation and undefined tray moment are mixed; no cause is isolated there.\n\nR3 : s Mathematical port translates ± 1 µm **prescribed**, not measured, error box per implant and bone reference reading to regional interval 27,25 – 35,25 and 261,625 – 269,625 µm respectively. All 512 exact rational box corner is within the range. Incorrect +10 µm reading fails against the third load case. This enclosure applies only to the specified measuring box, exactly geometry/last and the same linear branch; spatial residual field and biological outcome is UNKNOWN .\n\nMeasure minimum two separated implant markers with local bone references, under two independent forces / torque; use a third load for validation. An entire 3D case needs sufficient channels for six degrees of freedom. Pressure and friction require a separate normal/tangential measurement ; peak-IT alone does not separate these from the cutting and contact area.\n\n## Apostasy and bounds\n\n{len(ledger)} search file paths ({len({d['pmcid'] for d in ledger})} unika publikationer), {rejected} rejected ({100 * rejected / len(ledger):.2f}%). Five preserved paths correspond to four independent movement studies: PMC10792929 is available two times. Reasons are reported entry by entry and summarized in results.json : secondary source, error domain / interface , missing load/unit/table or simulated quantity . PMC9917810 : s Tabled M-Equation does not have device indication and is not taken as absolute µm - reference . PMC11000944 : s slide table is FE - outputs ; its system table also has an incorrect 6026 cell and unclear independent relationship to the 2017 setup.\n\nThe removal is based on targeted primary source reading and automatic title/article type/tabletability screening. There is no comprehensive systematic overview and no evidence that direct local movement data is missing throughout the corpus or literature. UNKNOWN applies to the evidence actually included.\n\n**No clinical recommendation.** Osseointegration threshold is a phenomenological liability, not a universal individual condition. Mechanics→healing is HANDOVER, while cargo→movement is SIMULTANEOUS. Couplings and result are PENDING_INDEPENDENT_REVIEW .\n"""
